import{_ as g}from"./chunks/image1.kwsHSrsc.js";import{_ as o}from"./chunks/image2.UYnXny4D.js";import{_ as r}from"./chunks/image3.z0vX6Nw7.js";import{_ as n,c as s,o as l,ae as e}from"./chunks/framework.B8KKhRA6.js";const m=JSON.parse('{"title":"3-2. 수익사업 매뉴얼","description":"","frontmatter":{"title":"3-2. 수익사업 매뉴얼"},"headers":[],"relativePath":"manual/3-2._수익사업_매뉴얼.md","filePath":"manual/3-2._수익사업_매뉴얼.md"}'),a={name:"manual/3-2._수익사업_매뉴얼.md"};function i(p,t,u,h,c,d){return l(),s("div",null,t[0]||(t[0]=[e('<blockquote><p><strong>☆ 수익사업 매뉴얼☆</strong></p><p><strong>Ⅰ</strong></p><p><strong>수익사업이란?</strong></p></blockquote><h1 id="수익사업이란" tabindex="-1">수익사업이란? <a class="header-anchor" href="#수익사업이란" aria-label="Permalink to &quot;수익사업이란?&quot;">​</a></h1><ul><li>수익사업은 일반적으로 금전적 대가를 받고 재화나 서비스를 제공하는 사업으로서, 제조업, 건설업, 도매 및 소매업 등 한국표준산업분류에 따른 사업으로 아주 포괄적으로 규정되어있음</li></ul><blockquote><p>(법인세법 제4조 제3항 참조)</p><p>따라서 재단이 관리 운영 중 발생하는 공연수입, 대관수입, 카페수입 등은 법인세법상 수익사업에 해당함</p></blockquote><ul><li>물론 동법시행령 제3조 제1항에서 비영리내국법인의 수익사업에서 제외되는 사업을 열거하고 있으나, 재단의 수익사업 중 제외되는 수익사업은 없음</li></ul><h1 id="재단-수익사업-현황-2024-09-기준" tabindex="-1">재단 수익사업 현황 (2024.09. 기준) <a class="header-anchor" href="#재단-수익사업-현황-2024-09-기준" aria-label="Permalink to &quot;재단 수익사업 현황 (2024.09. 기준)&quot;">​</a></h1><p>+----------------------+-----------------+-----------------------------------------------+--------------------------------+-----------+ | &gt; <strong>팀명</strong> | &gt; <strong>수익사업</strong> | &gt; <strong>업태/종목</strong> | &gt; <strong>매출방법</strong> | &gt; <strong>VAT</strong> | +:====================:+:===============:+===============================================+:==============================:+:=========:+ | &gt; 공연기획팀 | &gt; 공연장대관 | &gt; 서비스/예술관련대관 | &gt; 세금계산서, 현금영수증 | &gt; 과세 | +----------------------+-----------------+-----------------------------------------------+--------------------------------+-----------+ | &gt; 공연기획팀 | &gt; 공연수입 | &gt; 서비스/공연장운영 | &gt; 신용카드, 계산서, 현금영수증 | &gt; 면세 | +----------------------+-----------------+-----------------------------------------------+--------------------------------+-----------+ | &gt; 예술청팀 | &gt; 카페수익 | &gt; 숙박및음식점업/커피전문점 | &gt; 신용카드 | &gt; 과세 | +----------------------+-----------------+-----------------------------------------------+--------------------------------+-----------+ | &gt; 예술청팀 | &gt; 공간대관 | &gt; 서비스/예술관련대관 | &gt; 세금계산서, 현금영수증 | &gt; 과세 | +----------------------+-----------------+-----------------------------------------------+--------------------------------+-----------+ | &gt; 금천예술공장 | &gt; 공간대관 | &gt; 서비스/예술관련대관 | &gt; 세금계산서, 현금영수증 | &gt; 과세 | +----------------------+-----------------+-----------------------------------------------+--------------------------------+-----------+ | &gt; 신당창작아케이드 | &gt; 공간대관 | &gt; 서비스/예술관련대관임대 | &gt; 현금영수증 | &gt; 과세 | +----------------------+-----------------+-----------------------------------------------+--------------------------------+-----------+ | &gt; 융합예술팀 | &gt; 공간대관 | &gt; 서비스/예술관련임대 | &gt; 세금계산서, 현금영수증 | &gt; 과세 | +----------------------+-----------------+-----------------------------------------------+--------------------------------+-----------+ | &gt; 연희문학창작촌 | &gt; 공간대관 | &gt; 서비스업/예술관련대관임대 | &gt; 현금영수증 | &gt; 과세 | +----------------------+-----------------+-----------------------------------------------+--------------------------------+-----------+ | &gt; 서울무용센터 | &gt; 공간대관 | &gt; 서비스/예술관련임대 | &gt; 세금계산서, 현금영수증 | &gt; 과세 | +----------------------+-----------------+-----------------------------------------------+--------------------------------+-----------+ | &gt; 서울연극센터 | &gt; 공간대관 | &gt; 부동산업/비거주용 건물 임대업(점포, 타인땅) | &gt; 세금계산서, 현금영수증 | &gt; 과세 | +----------------------+-----------------+-----------------------------------------------+--------------------------------+-----------+ | &gt; 예술교육실 | &gt; 교육수입 | &gt; 교육서비스업/문화예술교육 | &gt; 세금계산서, 현금영수증 | &gt; 과세 | +----------------------+-----------------+-----------------------------------------------+--------------------------------+-----------+ | &gt; 홍보마케팅팀 | &gt; 인세수입 | &gt; 제조업/출판 | &gt; 세금계산서 | &gt; 과세 | +----------------------+-----------------+-----------------------------------------------+--------------------------------+-----------+ | &gt; 무대기자재공유센터 | &gt; 기자재대여 | &gt; 서비스업/공연의류및소품대여 | &gt; 현금영수증 | &gt; 과세 | | | &gt; | &gt; | | | | | &gt; (온,오프라인) | &gt; 도매 및 소매업/전자상거래업 | | | +----------------------+-----------------+-----------------------------------------------+--------------------------------+-----------+</p><blockquote><p><strong>Ⅱ</strong></p><p><strong>수익사업 개시 전 검토사항</strong></p><p><strong>수익사업 개시 전 검토사항</strong></p></blockquote><ul><li><p>기본(조례/정관) 검토 : 재단이 할 수 있는 사업인가?</p></li><li><p>세무관련 검토사항 : 자체사업인가? 수탁사업인가?</p></li><li><p>추가적인 세무관련 검토사항 : 수탁사업이라면 수탁사업의 형태가 어떠한가 ?</p></li></ul><h1 id="기본검토사항-재단이-할-수-있는-사업인가" tabindex="-1">기본검토사항 (재단이 할 수 있는 사업인가?) <a class="header-anchor" href="#기본검토사항-재단이-할-수-있는-사업인가" aria-label="Permalink to &quot;기본검토사항 (재단이 할 수 있는 사업인가?)&quot;">​</a></h1><ul><li>검토사항 : 조례 및 정관</li></ul><p>+--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+ | &gt; <strong>조 례</strong> | &gt; <strong>정 관</strong> |  | &gt; 제3조(업무) | &gt; 제1조(목적) | | | &gt; | | 1. 문화예술의 창작·보급 및 문화예술활동의 지원 | &gt; ① 이 법인은 「민법」(이하 &quot;법&quot;이라 한다)과 「서울특별시 재단법 인 서울문화재단 설립 및 운영에 관한 조례」(이하 &quot;조례&quot;라 한다) 가 정하는 바에 의하여 시민의 자율적인 문화예술활동을 진작시 켜 서울의 문화예술진흥을 도모하기 위하여 문화예술진흥과 시민 의 문화예술활동 지원을 목적으로 한다 | | | &gt; | | 2. 문화예술의 교육 및 연구 | &gt; 제5조(수익사업) 재단은 제1조의 규정에 의하여 설립목적의 범위안 에서 시장의 승인을 얻어 수익사업을 할 수 있다 | | | | | 3. 국내·외 문화예술 교류 | | | | | | 4. 시민의 문화향수 및 창의력 증진 | | | | | | 5. 지역문화의 육성·지원 및 지역문화 전문인력 양성 | | | | | | 6. 그 밖에 법인의 목적달성에 필요한 사업 | | | | | | &gt; 제11조(수익사업) 재단은 설립목적의 범위안에서 시장의 사전승인 을 얻어 수익사업을 할 수 있다 | | | &gt; | | | &gt; 제14조(사업의 대행) 재단은 국가,시 또는 자치구의 문화시설 운영 또는 문화진흥 사업을 위탁받아 수행하거나 대행할 수 있으며, 이 경우 필요한 비용부담은 국가,시 또는 자치구가 부담한다 | | +--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+</p><h1 class="underline" id="→-판단하기-어렵거나-애매한-경우-고문변호사를-통한-법률-자문필수" tabindex="-1">→ [판단하기 어렵거나 애매한 경우, 고문변호사를 통한 법률 자문필수!] <a class="header-anchor" href="#→-판단하기-어렵거나-애매한-경우-고문변호사를-통한-법률-자문필수" aria-label="Permalink to &quot;→ [판단하기 어렵거나 애매한 경우, 고문변호사를 통한 법률 자문필수!]{.underline}&quot;">​</a></h1><ul><li><strong>개시 전 사전절차</strong> ※ 수익사업 개시 전 1회 진행</li></ul><h2 id="자체사업" tabindex="-1">자체사업 <a class="header-anchor" href="#자체사업" aria-label="Permalink to &quot;자체사업&quot;">​</a></h2><p>+-----------------------------------------------------------------------------+--------------------------------------------+---------------------------------------+--------------------------------------------+ | &gt; <strong>구 분</strong> | &gt; <strong>절차 1</strong> | &gt; <strong>절차 2</strong> | &gt; <strong>절차 3</strong> | +:===========================================================================:+:==========================================:+=======================================+============================================+ | &gt; 재단에서 추진하고 있지 않은 &#39;새로운 종류의 수익사업&#39;을 | &gt; 경영기획팀 문의(고문변호사 자문) | &gt; 이사회 승인 (경영기획팀) | &gt; 서울시 승인 (경영기획팀) | | &gt; | &gt; | | | | &gt; 개시하고자 할 때 | &gt; ※재단 목적사업 범위에 속하는지 확인 필요 | | | +-----------------------------------------------------------------------------+--------------------------------------------+---------------------------------------+--------------------------------------------+ | &gt; 재단에서 &#39;추진하고 있는&#39; 수익사업을 새로운 사업/공간에서 개시하고자 할 때 | &gt; 경영기획팀 고지 | &gt; 차년도 | &gt; 차년도 예산편성 서울시 승인 (경영기획팀) | | | | &gt; | | | | | &gt; 수입예산 편성 (수익사업 종료 시까지 | | | | | &gt; | | | | | &gt; 매년편성) | | +-----------------------------------------------------------------------------+--------------------------------------------+---------------------------------------+--------------------------------------------+</p><blockquote><p>※ 현재 기준 &#39;추진 중&#39; 수익사업 종류 : 대관, 프로그램(참가료), 카페운영, 티켓판매, 출판(간행물)</p></blockquote><h2 id="수탁사업-행정재산-관리위탁-포함" tabindex="-1">수탁사업 (행정재산 관리위탁 포함) <a class="header-anchor" href="#수탁사업-행정재산-관리위탁-포함" aria-label="Permalink to &quot;수탁사업 (행정재산 관리위탁 포함)&quot;">​</a></h2><p>+---------------------------------------------------------------------------+----------------------------------------------+----------------------------------------------+----------------------------+ | &gt; <strong>구 분</strong> | &gt; <strong>절차 1</strong> | &gt; <strong>절차 2</strong> | &gt; <strong>절차 3</strong> | +:=========================================================================:+==============================================+:============================================:+============================+ | &gt; 재단에서 추진하고 있지 않은 &#39;새로운 종류의 수익사업&#39;을 개시하고자 할 때 | &gt; 경영기획팀 문의(고문변호사 자문) | &gt; 기본계획에 포함하여 서울시 승인 (사업부서) | &gt; 이사회 보고 (경영기획팀) | | | &gt; | | &gt; | | | &gt; ※재단 목적사업 범위에 속하는지 확인 필요 | | &gt; ※ 사업자변경용 | +---------------------------------------------------------------------------+----------------------------------------------+----------------------------------------------+----------------------------+ | &gt; 재단에서 &#39;추진하고 있는&#39; 수익사업을 새로운 사업/공간에서 | &gt; 기본계획에 포함하여 서울시 승인 (사업부서) | &gt; 이사회 보고 (경영기획팀) | &gt; - | | &gt; | | &gt; | | | &gt; 개시하고자 할 때 | | &gt; ※사업자변경용 | | +---------------------------------------------------------------------------+----------------------------------------------+----------------------------------------------+----------------------------+</p><blockquote><p>※ 연도 중 추진 시 변경에 대한 서울시 승인 필요</p></blockquote><h1 id="세무관련-검토사항-※-재무회계팀-담당자-협의-필수" tabindex="-1">세무관련 검토사항 (※ 재무회계팀 담당자 협의 필수!) <a class="header-anchor" href="#세무관련-검토사항-※-재무회계팀-담당자-협의-필수" aria-label="Permalink to &quot;세무관련 검토사항 (※ 재무회계팀 담당자 협의 필수!)&quot;">​</a></h1><ul><li>검토대상 : 법인세법, 공익법인회계기준, 부가가치세법</li></ul><p><strong>[※ 참고 : 관련 법령]</strong></p><p>+------------------------------------+------------------------------------+-----------------------------------------------+ | &gt; <strong>법인세법1)</strong> | &gt; <strong>공익법인회계기준</strong> | &gt; <strong>부가가치세법</strong> | +:==================================:+:==================================:+:=============================================:+ | &gt; 고유목적사업 vs 수익사업 | &gt; 공익목적사업 vs 기타사업2) | &gt; 과세3) vs 면세4) vs (과세·면세)안분5) | +------------------------------------+------------------------------------+-----------------------------------------------+ | &gt; (구분경리6)) 더존IU의 &#39;지출·수입결의등록&#39;에서 [회계단위]로 구분 | &gt; &#39;지출·수입결의등록&#39;에서 [세무구분]로 구분 | +-------------------------------------------------------------------------+-----------------------------------------------+</p><h1 id="자체예산으로-수익사업-하는-경우" tabindex="-1">자체예산으로 수익사업 하는 경우 <a class="header-anchor" href="#자체예산으로-수익사업-하는-경우" aria-label="Permalink to &quot;자체예산으로 수익사업 하는 경우&quot;">​</a></h1><ul><li class="underline"><p>[재단이 시민(이용자)에게 제공하는 용역 및 재화에 대한 세무처리]</p></li><li><p><img src="'+g+'" alt="" width="0.31591535433070866in" height="0.3802077865266842in">각 법령별 해당사항 체크 <strong>(※ 예시)</strong></p></li></ul><p>+------------------+------------------------------------+------------------------------------+-----------------------------------------------+ | &gt; <strong>수익사업</strong> | &gt; <strong>법인세법</strong> | &gt; <strong>공익법인회계기준</strong> | &gt; <strong>부가가치세법</strong> | +:================:+:==================================:+:==================================:+:=============================================:+ | &gt; 공연장대관 | &gt; <s>고유목적사업</s> vs <strong>수익사업</strong> | &gt; <strong>공익목적사업</strong> vs <s>기타사업</s> | &gt; <strong>과세</strong> vs <s>면세</s> vs <strong>(과세·면세)안분</strong> | +------------------+------------------------------------+------------------------------------+-----------------------------------------------+ | &gt; 공연 수입 | &gt; <s>고유목적사업</s> vs <strong>수익사업</strong> | &gt; <strong>공익목적사업</strong> vs <s>기타사업</s> | &gt; <s>과세</s> vs <strong>면세</strong> vs <strong>(과세·면세)안분</strong> | +------------------+------------------------------------+------------------------------------+-----------------------------------------------+ | &gt; 카페 수입 | &gt; <s>고유목적사업</s> vs <strong>수익사업</strong> | &gt; <s>공익목적사업</s> vs <strong>기타사업</strong> | &gt; <strong>과세</strong> vs <s>면세</s> vs <strong>(과세·면세)안분</strong> | +------------------+------------------------------------+------------------------------------+-----------------------------------------------+ | &gt; 인세 수입 | &gt; <s>고유목적사업</s> vs <strong>수익사업</strong> | &gt; <strong>공익목적사업</strong> vs <s>기타사업</s> | &gt; <strong>과세</strong> vs <s>면세</s> vs <strong>(과세·면세)안분</strong> | +------------------+------------------------------------+------------------------------------+-----------------------------------------------+ | &gt; 지원금이자반납 | &gt; <strong>고유목적사업</strong> vs <s>수익사업</s> | &gt; <strong>공익목적사업</strong> vs <s>기타사업</s> | &gt; 해당사항 없음 | +------------------+------------------------------------+------------------------------------+-----------------------------------------------+</p><p>+------------+-------------------------------------------------------------+------------------------------------------------------------+ | &gt; <strong>구분</strong> | &gt; <strong>(부가가치세) 과세</strong> | &gt; <strong>(부가가치세) 면세</strong> | +:==========:+=============================================================+============================================================+ | &gt; 정의 | &gt; 부가가치세 면세로 명시되어있는 재화 및 용역의 공 | &gt; 부가가치세법 제26조(재화 또는 용역의 공급에 대한 면세) | | | &gt; | &gt; | | | &gt; 급을 제외한 모든 재화 및 용역의 공급에 적용 | &gt; 에 따라 명시되어있는 재화 및 용역의 공급만 면세를 적용 | +------------+-------------------------------------------------------------+------------------------------------------------------------+ | &gt; 예시 | &gt; 부동산 임대, 주차장, 공연장 대관 등 | &gt; 공연수입 등 고유목적사업의 수입 | | | | &gt; | | | | &gt; (단, 실비요건을 만족할 수 있는 정도의 수입일 경우) | +------------+-------------------------------------------------------------+------------------------------------------------------------+ | &gt; 처리방법 | &gt; 세금계산서 또는 현금영수증(과세) 발행 후 부가세 신고·납부 | &gt; 계산서 또는 현금영수증(면세) 발행 후 부가세 신고 | +------------+-------------------------------------------------------------+------------------------------------------------------------+ | &gt; 안분 | &gt; (대상) 부가가치세 과세대상과 면세대상의 사업을 **[겸업]{.underline}**하는 경우 | | | &gt; | | | &gt; (방법) 해당 건에 대한 더존IU에서 세금계산서 [지출결의등록] 입력시 [불공제사유 : 공통매입세액안분계산서분] 선택 | | | &gt; | | | &gt; (신고) 과세사업과 면세사업에 공통으로 사용하는 비용에 대해 매출세금계산서 금액 비율에 따라 나눠서 부가세 신고 | +------------+--------------------------------------------------------------------------------------------------------------------------+</p><ol><li><p>제4조(과세소득의 범위) 제조업, 건설업, 도매 및 소매업 등 통계법 제22조에 따라 통계청장이 작성 고시하는 한국표준산업분류에 따른 사업으 로서 대통령령으로 정하는 것</p></li><li><p>정관상 목적사업이라 하더라도 공익목적사업으로 볼 수 없는 사업이나 공익목적활동에 부수적으로 발생하는 기념품 판매, 카페, 임대, 적극적인 금융자산 투자 등은 기타사업으로 분류</p></li><li><p>부가가치세 면세로 명시되어있는 재화 및 용역의 공급을 제외한 모든 재화 및 용역의 공급에 적용</p></li><li><p>부가가치세법 제26조(재화 또는 용역의 공급에 대한 면세)에 따라 명시되어있는 재화 및 용역의 공급만 면세를 적용</p></li><li><p>부가가치세 과세대상과 면세대상의 사업을 겸업하는 경우, 과세사업과 면세사업에 공통으로 사용하는 경우, 부가가치세 안분계산을 하여야 함</p></li><li><p>제113조(구분경리) ① 비영리법인이 수익사업을 하는 경우에는 자산,부채 및 손익을 그 수익사업에 속하는 것과 수익사업이 아닌 그 밖의 사업에 속하는 것을 각각 다른 회계로 구분하여 기록하여야 한다</p></li></ol><ol start="2"><li><strong>[수탁사업]{.underline}</strong></li></ol><h4 id="_1-1-수탁사업이-위탁기관-서울시-등-↔-재단-간의-협약-체결-underline-인-경우" tabindex="-1">①-1 수탁사업이 [위탁기관(서울시 등) ↔ 재단 간의 협약 체결]{.underline} 인 경우 <a class="header-anchor" href="#_1-1-수탁사업이-위탁기관-서울시-등-↔-재단-간의-협약-체결-underline-인-경우" aria-label="Permalink to &quot;①-1 수탁사업이 [위탁기관(서울시 등) ↔ 재단 간의 협약 체결]{.underline} 인 경우&quot;">​</a></h4><p>+----------------------------------------------------------------------------+----------------------------------------------------------------------------+-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+ | <strong>법인세법</strong> | &gt; <strong>공익법인회계기준</strong> | &gt; <strong>부가가치세법</strong> | +:==========================================================================:+:==========================================================================:+:=============================================================================================================================================================================================================================:+ | <strong>고유목적사업</strong> vs 수익사업 | &gt; <strong>공익목적사업</strong> vs 기타사업 | &gt; 과세 vs 면세 | +----------------------------------------------------------------------------+----------------------------------------------------------------------------+-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+ | &gt; 조례·정관+법인세법/공익법인회계기준상 해당여부 판단 | &gt; ▶ 재단이 관리·운영 업무 전체를 위임 받아 이를 관리·운영할 책임을 부담할 예정이고, | | | &gt; | | | &gt; ▶ 인력을 직접 고용하여 본 건의 용역을 수행할 계획이며, | | | &gt; | | | &gt; ▶ 재단 명의로 제3자와의 계약을 체결하고 재단의 계산으로 외주비 등을 지급할 뿐만 아니라 재단 명의로 세금계산서를 수 수하고 부가가치세를 신고하는 등 용역을 수행하는 과정에서 재단 본인 명의와 계산으로 사업비를 지출한다면!! | | | &gt; | | | &gt; → 수탁자의 인건비 등 내부비용을 포함한 전체 대가(총사업비)는 | | | &gt; | | | &gt; <strong>[부가가치세 공급가액에 포함(과세 또는 면세)]{.underline}<strong>해야 함 | +---------------------------------------------------------------------------------------------------------------------------------------------------------+ | | &gt; [※ 참고] | | | &gt; | | | &gt; ▶ 비영리법인이 지방자치단체로부터 위탁 받은 사업을 영위하면서 위수탁협약에 따라 해당 사업에서 발생한 손익이 실질적으로 지방자치단체에 귀속될 경우 | | | &gt; | | | &gt; (</strong>[단, 대가를 받지 않아야함)]{.underline}</strong>, | | | &gt; | | | &gt; ▶ 해당사업은 법인세법 제2조제3항에 따라 법인세법상 과세대상 사업에 해당하지 않음 | | | &gt; | | | &gt; → 구분경리는 수행할 필요가 없음 (서면-2020-법인 | | | &gt; | | | &gt; -2184(20200727))7) | | +---------------------------------------------------------------------------------------------------------------------------------------------------------+ | | | | +---------------------------------------------------------------------------------------------------------------------------------------------------------+-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+</p><ul><li><p><strong>총 사업비의 과세 또는 면세 여부</strong></p><ul><li><p>&#39;부가가치세법 제26조8), 부가가치세법 시행령 제45조9) 및 같은 법 시행규칙 제34조 제1항10)&#39;에 따라 **[&#39;고유의]{.underline} [사업목적&#39;]{.underline}**을 위하여 **[실비 또는 무상]{.underline}**으로 공급하는 재화 또는 용역의 경우 <strong>[면세]{.underline}</strong></p></li><li><p>실비 또는 무상으로 <strong>[공급하지 못한다면]{.underline}</strong> 위탁사업의 **[총사업비 기준으로 부가가치세 10% 편성]{.underline}**하여 사업비 입금 시 국세청 신고 후 납부해야 함</p></li></ul></li></ul><blockquote><p>[※ 참고 : 서울시 민간위탁사무 예산·회계 매뉴얼 (7.2 위탁사업의 납세의무자 및 공급가액 산정기준)11)]</p></blockquote><h4 id="부가가치세-면세를-위한-조건" tabindex="-1">부가가치세 면세를 위한 조건 <a class="header-anchor" href="#부가가치세-면세를-위한-조건" aria-label="Permalink to &quot;부가가치세 면세를 위한 조건&quot;">​</a></h4><ul><li><p><strong>무상 공급 충족 조건 :</strong> 위탁대행수수료 미수령</p></li><li><p><strong>실비 공급 충족 조건 :</strong> 직접인건비12)(수탁사업 인력)를 대행수수료 이상으로 자체예산으로 지급</p></li></ul><p><img src="'+o+'" alt="" width="6.749290244969379in" height="1.6264577865266843in"></p><ol start="7"><li><p>서면-2020-법인-2184(20200727) 비영리법인이 지방자치단체로부터 위탁받은 청소년수련관 운영사업(이하 &quot;해당사업&quot;)을 영위하면서 해당사 업에서 발생한 손익이 실질적으로 지방자치단체에 귀속될 경우, 법인세가 과세되지 아니하는 것임</p></li><li><p>① 다음 각 호의 재화 또는 용역의 공급에 대하여는 부가가치세를 면제한다.</p></li></ol><blockquote><p>18. 종교, 자선, 학술, 구호(救護), 그 밖의 공익을 목적으로 하는 단체가 공급하는 재화 또는 용역으로서 대통령령으로 정하는 것</p></blockquote><ol start="9"><li>법 제26조제1항제18호에 따른 종교, 자선, 학술, 구호(救護), 그 밖의 공익을 목적으로 하는 단체가 공급하는 재화 또는 용역은 다음 각 호의 재화 또는 용역으로 한다.</li></ol><blockquote><p>1. 주무관청의 허가 또는 인가를 받거나 주무관청에 등록된 단체(종교단체의 경우에는 그 소속단체를 포함한다)로서 「상속세 및 증여세법 시 행령」 제12조 각 호의 어느 하나에 따른 사업 또는 기획재정부령으로 정하는 사업을 하는 단체가 그 고유의 사업목적을 위하여 일시적으로 공급하거나 실비(實費) 또는 무상으로 공급하는 재화 또는 용역</p></blockquote><ol start="10"><li><p>① 영 제45조제1호에서 &quot;기획재정부령으로 정하는 사업&quot;이란 비영리법인의 사업으로서 종교, 자선, 학술, 구호, 사회복지, 교육, 문화, 예술 등 공익을 목적으로 하는 사업을 말한다.</p></li><li><p>공익법인이 고유의 사업목적을 위하여 실비로 공급하는 용역에 해당하면 부가가치세가 면제되지만 이에 해당하지 않는 경우 부가가치세 과 세 및 납부대상임 (조심2016중1523, 20170809)</p></li><li><p>직접인건비 : 수탁사업을 전담하는 수탁사업팀의 팀원 및 팀장 인건비</p></li></ol><h4 id="_1-2-수탁사업이-대행계약인-경우" tabindex="-1">①-2 수탁사업이 대행계약인 경우 <a class="header-anchor" href="#_1-2-수탁사업이-대행계약인-경우" aria-label="Permalink to &quot;①-2 수탁사업이 대행계약인 경우&quot;">​</a></h4><ul><li>재단의 고유목적사업이 아닌 사업의 대행계약 체결하는 경우</li></ul><blockquote><p>- 예시) 거리예술창작센터 리모델링사업, 예술청ISP 개발 사업</p><p>※ 회계팀에 별도문의 요청 (현재 없음)</p></blockquote><h4 id="_2-수탁사업-수행-중-수익사업-하는-경우" tabindex="-1">② 수탁사업 수행 중 수익사업 하는 경우 <a class="header-anchor" href="#_2-수탁사업-수행-중-수익사업-하는-경우" aria-label="Permalink to &quot;② 수탁사업 수행 중 수익사업 하는 경우&quot;">​</a></h4><ul><li class="underline">[재단이 시민(이용자)에게 제공하는 운영관련 수익에 대한 세무처리]</li></ul><p>+------------+--------------------------------------------+------------------------------------------------------+ | &gt; <strong>구분</strong> | &gt; <strong>(부가가치세) 과세</strong> | &gt; <strong>(부가가치세) 면세</strong> | +============+============================================+======================================================+ | &gt; 정의 | &gt; 부가가치세 면세로 명시되어있는 재화 및 | &gt; 부가가치세법 제26조(재화 또는 용역의 공급에 대 | | | &gt; | &gt; | | | &gt; 용역의 공급을 제외한 모든 재화 및 용역 | &gt; 한 면세)에 따라 명시되어있는 재화 및 용역의 공 | | | &gt; | &gt; | | | &gt; 의 공급에 적용 | &gt; 급만 면세를 적용 | +------------+--------------------------------------------+------------------------------------------------------+ | &gt; 예시 | &gt; 부동산 임대, 주차장, 공연장 대관 등 | &gt; 공연수입 등 고유목적사업의 수입 | | | | &gt; | | | | &gt; (단, 실비요건을 만족할 수 있는 정도의 수입일 경우) | +------------+--------------------------------------------+------------------------------------------------------+ | &gt; 처리방법 | &gt; 세금계산서 또는 현금영수증(과세) 발행 후 | &gt; 계산서 또는 현금영수증(면세) 발행 후 부가세 신고 | | | &gt; | | | | &gt; 부가세 신고·납부 | | +------------+--------------------------------------------+------------------------------------------------------+</p><p>+--------------------+------------------------------------------------------------+ | &gt; <strong>법인세법</strong> | &gt; 고유목적사업 vs 수익사업 : 관련 법령 검토 | +====================+============================================================+ | &gt; <strong>공익법인</strong> | &gt; 공익목적사업 vs 기타사업 | | &gt; | &gt; | | &gt; <strong>회계기준</strong> | &gt; → 공익법인회계기준상 해당여부 판단 | +--------------------+------------------------------------------------------------+ | &gt; <strong>부가가치세법</strong> | | +--------------------+------------------------------------------------------------+</p><h4 class="underline" id="_3-위수탁협약서-에-이자수입-비과세-통장개설-관련-조항-삽입-요청" tabindex="-1">③ [&#39;위수탁협약서&#39;에 이자수입 비과세 통장개설 관련 조항 삽입 요청] <a class="header-anchor" href="#_3-위수탁협약서-에-이자수입-비과세-통장개설-관련-조항-삽입-요청" aria-label="Permalink to &quot;③ [&#39;위수탁협약서&#39;에 이자수입 비과세 통장개설 관련 조항 삽입 요청]{.underline}&quot;">​</a></h4><ul><li>[이자수입 비과세 통장13)]{.underline}으로 개설</li></ul><p>+-------------------------------------------------------------------------------------------------------+----------------------------------------------------+ | &gt; <strong>일반계좌</strong> | &gt; <strong>[이자수입 비과세 계좌]{.underline}</strong> | +=======================================================================================================+====================================================+ | &gt; ▶ 이자소득법인세는 이자 수입 발생 시 원천징수되어 계좌에 세금(이자소득·주민세)을 제외한 금액만 입금 | &gt; ▶ 이자소득·주민세 차감없이 이자수입이 전액 입금 | | &gt; | &gt; | | &gt; ▶ 이자소득·주민세는 법인세 신고 후 결과에 따라 익년도에 | &gt; ▶ 해당연도 사업비 정산시 바로 수입금 반납이 가능 | | &gt; | | | &gt; 5~6월 환급→서울시로 추가 반납 필요 | | +-------------------------------------------------------------------------------------------------------+----------------------------------------------------+</p><ul><li>요청사항 : <strong>[협약서]{.underline}</strong> 내 해당 <strong>[이자수입이 전액 시금고 귀속 예정으로 비과세대상이라는 조항]{.underline}</strong> 명시</li></ul><blockquote><p>- 비과세 요건을 만족하기 위해 해당 조항을 반드시 추가해야 비과세 통장개설 가능</p><p>[예시] 제OO조 O항 &quot;사업비 계좌에서 발생하는 이자수입은 시금고에 귀속될 예정으로 비과세 대상이며, 발생된 이자 (사업기간 중 전 기간에 걸쳐 발생된 이자)는 집행잔액과 같이 &quot;시&quot;에 반납하여야 한다.</p></blockquote><ol start="13"><li>법인세법 제3조 제2항(납세의무자) : 내국법인 중 국가와 지방자치단체(지방자치단체조합을 포함한다. 이하 같다)는 그 소득에 대한 법인세를 납부할 의무가 없다.</li></ol><blockquote><p>법인세법 제73조 제2항(내국법인의 이자소득 등에 대한 원천징수) : 법인세가 부과되지 아니하거나 면제되는 소득 등 대통령령으로 정하는 소득에 대해서는 법인세를 원천징수하지 아니한다.</p><p>국세기본법 제14조 제1항(실질과세) : 과세의 대상이 되는 소득, 수익, 재산, 행위 또는 거래의 귀속이 명의(名義)일 뿐이고 사실상 귀속되는 자가 따로 있을 때에는 사실상 귀속되는 자를 납세의무자로 하여 세법을 적용한다.</p><p><strong>Ⅲ</strong></p><p><strong>수익사업 개시를 위한 업무절차</strong></p></blockquote><h1 id="업무절차" tabindex="-1">업무절차 <a class="header-anchor" href="#업무절차" aria-label="Permalink to &quot;업무절차&quot;">​</a></h1><blockquote><p><strong>⇨ ⇨ ⇨</strong></p></blockquote><p>+-----------------------------------------------------------------------+ | &gt; <strong>1. 관련사업을 위한 인허가</strong> | +=======================================================================+ | &gt; <strong>사업부서</strong> | +-----------------------------------------------------------------------+ | &gt; · 필요사항 확인 | | &gt; | | &gt; →관할구청 신고(ex카페, 공연장) | +-----------------------------------------------------------------------+</p><p>+-----------------------------------------------------------------------+ | &gt; <strong>2. 사업자등록</strong> | +:=====================================================================:+ | &gt; <strong>사업부서/재무회계팀</strong> | +-----------------------------------------------------------------------+ | - 협조문 발송 | | | | &gt; [수신:재무회계팀] | | | | - 관할 세무서 방문 | | | | &gt; 업종 및 업태추가 | +-----------------------------------------------------------------------+</p><p>+-----------------------------------------------------------------------+ | &gt; <strong>3. 계좌 개설 및 회계처리 등 확인사항</strong> | +=======================================================================+ | &gt; <strong>사업부서/재무회계팀</strong> | +-----------------------------------------------------------------------+ | - 공과금 안분고려 | | | | - 통장 별도구분 필요 | | | | - 예산,회계단위 확인 | +-----------------------------------------------------------------------+</p><p>+-----------------------------------------------------------------------+ | &gt; <strong>4. 수익사업 개시 및 업무처리</strong> | +=======================================================================+ | &gt; <strong>사업부서</strong>/<strong>재무회계팀</strong> | +-----------------------------------------------------------------------+ | - 수익 발생시 | | | | &gt; 수입결의서 작성 방식 | | | | - 부가세 등 세무신고 및 | | | | &gt; 결산 등 업무처리 | +-----------------------------------------------------------------------+</p><h1 id="단계별-세부사항" tabindex="-1">단계별 세부사항 <a class="header-anchor" href="#단계별-세부사항" aria-label="Permalink to &quot;단계별 세부사항&quot;">​</a></h1><h3 id="관련사업을-위한-인허가-사업부서" tabindex="-1">관련사업을 위한 인허가 [사업부서] <a class="header-anchor" href="#관련사업을-위한-인허가-사업부서" aria-label="Permalink to &quot;관련사업을 위한 인허가 \\[사업부서\\]&quot;">​</a></h3><ul><li>영업을 위한 인허가 검토 (※ <strong>[관할구청별로 서류가 다르기에 구청에 제출서류를 먼저 문의하는 것은 필수!!)]{.underline}</strong></li></ul><blockquote><p>- <strong>(예시) 카페 및 공연장 인허가 순서 및 서류 (예시입니다!! 반드시 문의해주세요)</strong></p></blockquote><p>+--------------+-------------------------------------------------------------------------------------------+----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+ | &gt; <strong>구분</strong> | &gt; <strong>절차</strong> | &gt; <strong>관할구청 신고 필요서류</strong> |  | &gt; <strong>카페</strong> | &gt; ▶ 식품위생교육 교육이수 및 위생교육수료증 수령 (인터넷강의 가능) | &gt; 위생교육수료증, 보건증, 식품영업신고서, 대리인신분증, 법인인감증명서, 법인등기 부등본, 사용인감계, 사용인감, 위임장 등 | | | &gt; | | | | &gt; ▶ 보건소 또는 지정병원에서 검사 후 보건증 수령 (&quot;모든&quot; 근무자) | | | | &gt; | | | | &gt; - 보건증은 1년마다 갱신하여야함 | | | | &gt; | | | | &gt; ▶ 관할 구청 위생과에 방문하여 식품영업신고서 작성 (구청에 구비) | | | | &gt; | | | | &gt; ▶ 관련서류 구비하여 관할 구청 방문하여 영업신고증 수령 | | | | &gt; | | | | &gt; (30일이내에 시설조사 나올수도있음) | | +--------------+-------------------------------------------------------------------------------------------+----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+ | &gt; <strong>공연장</strong> | &gt; ▶ 사업자등록 없을 경우, (세무서)사업자등록→(구청)공연장등록→(세무서)공연장관련 업태추가 | &gt; 시설설치내역서, 시설의 평면도 및 배치 도, 부동산 소유권 또는 사용권을 증명할 수 있는 서류, 안전검사 결과 관련 서류, 피난대피도, 재해대처계획신고서, 전기안 전점검확인서(한국전기안전공사), 방염성 능검사성적서(소방서 발급) 등 | | | &gt; | | | | &gt; ▶ 사업자등록 있을 경우, (구청)공연장등록→(세무서)공연장관련 업태추가 | | | | &gt; | | | | &gt; &lt;공연장 등록관련-자세한 사항은 구청에 문의!&gt; | | | | &gt; | | | | &gt; ▶ 공연장 등록 전 지정된 기관에서 안전검사→안전검사 결과 수령 | | | | &gt; | | | | &gt; ※ 신규공연장등록시 | | | | | | | | - 설계검토결과서(기구 또는 기계수 40개 이상만 해당) | | | | | | | | - 등록 전 안전검사 결과서 | | | | | | | | &gt; ※ 변경등록시 | | | | | | | | - 정기검사결과 또는 정밀안전진단 결과서 | | | | | | | | &gt; ▶ 관련 서류 구비하여 관할 구청에 방문→공연장 등록증 수령 | | +--------------+-------------------------------------------------------------------------------------------+----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+</p><h3 id="사업자등록-사업부서-재무회계팀" tabindex="-1">사업자등록 [사업부서 / 재무회계팀] <a class="header-anchor" href="#사업자등록-사업부서-재무회계팀" aria-label="Permalink to &quot;사업자등록 \\[사업부서 / 재무회계팀\\]&quot;">​</a></h3><ul><li><p>사업자등록 : 납세 의무를 지는 사업자에 관한 정보를 국세청(관할세무서)에 신고 및 등록하는 것</p><ul><li>신규 사업자등록 : 아래 서류 첨부하여 협조문 발송 [수신 : 재무회계팀]</li></ul></li></ul><blockquote><p>① 기본 붙임문서(필수) : 건물소유주 등기부등본, 임대차계약서(건물의 사용허가 관련서류), 이사회 회의록, 사업기본계획</p><p>② 추가 붙임문서 (해당사항 있는 경우) : 위수탁협약서, 영업신고증, 공연장등록증 등 (업종업태별 상이)</p><p>③ 기타 (해당사항 있는 경우) : 임대업 해당 사업장은 추후 부가세 신고시 임대면적 필요</p></blockquote><ul><li><p>업태추가 : 협조문 발송 [수신 : 재무회계팀]</p><ul><li><p>업태에 따라 상이하므로 문의 후 진행</p></li><li><p>공연장 온라인 티켓판매시, 전자상거래업 종목 추가 협조 요청</p></li></ul></li></ul><blockquote><p><strong>→ 관련자료 확인 후 세무서 방문하여 신청 → 사업자등록증 공유</strong></p></blockquote><h3 id="계좌개설-및-회계처리-등-확인사항-사업부서-재무회계팀" tabindex="-1">계좌개설 및 회계처리 등 확인사항 [사업부서/재무회계팀] <a class="header-anchor" href="#계좌개설-및-회계처리-등-확인사항-사업부서-재무회계팀" aria-label="Permalink to &quot;계좌개설 및 회계처리 등 확인사항 \\[사업부서/재무회계팀\\]&quot;">​</a></h3><p>+--------------------------------+-------------------------------------------------------------------------------------------+ | &gt; <strong>업무</strong> | &gt; <strong>세부사항</strong> | +:==============================:+===========================================================================================+ | &gt; 관련 수입예산 편성 | &gt; ▶ 경영기획팀 문의 | | | &gt; | | | &gt; ▶ 지출 예산항목 중 수익사업과 관련된 예산 확보 필요 ex)대학로 공과금 | | | &gt; | | | &gt; ▶ 예산항목별 사용계좌가 달라질 수 있음 | +--------------------------------+-------------------------------------------------------------------------------------------+ | &gt; 관련 지출예산 관리 | &gt; ▶ 안분대상인 공과금은 사업비 내에 별도예산편성 | | | &gt; | | | &gt; ▶ 수익사업 관련 예산 항목 총액 협조문 발송 [수신: 재무회계팀] | | | &gt; | | | &gt; ▶ 별도 예산의 통장잔고가 부족한 경우, 회계 담당자에게 품의 증액 후 이체요청 협조문 발송 | | | &gt; | | | &gt; [수신: 재무회계팀] | +--------------------------------+-------------------------------------------------------------------------------------------+ | &gt; 수익사업용 계좌 및 카드 개설 | &gt; [자체사업] | | | &gt; | | | &gt; ▶ 수익사업 회계단위에서 사용하는 카드는 다른 회계단위에서 사용 금지 | | | &gt; | | | &gt; ▶ 신규 계좌·카드 필요시 협조문 발송 [수신: 재무회계팀] | | +-------------------------------------------------------------------------------------------+ | | &gt; [수탁사업] | | | &gt; | | | &gt; ▶ 위탁기관과 협의하여 필요계좌 및 법인카드 신청 | | | &gt; | | | &gt; ▶ 이자수익 비과세 개설을 위해 협약서에 관련 조항있는지 확인 | | | &gt; | | | &gt; ▶ 계좌·카드 개설 협조문 발송(기존계좌 사용할 때도 협조문 필요) [수신: 재무회계팀] | +--------------------------------+-------------------------------------------------------------------------------------------+ | &gt; 회계단위 확인 | &gt; ▶ 수익사업의 회계단위 확인하여 수입·지출 결의 (※ 아래 참고사항 확인) | +--------------------------------+-------------------------------------------------------------------------------------------+</p><p>+-----------------+-----------------------------------------------------------------------------------------------------------------------------------------+ | &gt; <strong>업무</strong> | &gt; <strong>세부사항</strong> | +=================+=========================================================================================================================================+ | &gt; 수입처리 방법 | &gt; [사업부서] | | | &gt; | | | &gt; ▶ 대금 결제 방법 결정 | | | | | | - 신용카드 | | | | | | - PG사 : 카드사별 가맹점 계약 불필요, 수수료 높음 | | | | | | - VAN사 : 카드사별 가맹점 계약 필요, 수수료 낮음 | | | | | | - 현금영수증 : 현금영수증 발급사이트 가입 및 발행처리 | | | | | | &gt; ▶ 수익처리방식 결정 | | +-----------------------------------------------------------------------------------------------------------------------------------------+ | | &gt; ▶ 수입결의 건별 과세/면세 구분 등 세무사항 관련 내용 공유 후 검토 | | | &gt; | | | &gt; ▶ 해당 수익의 입금방식 확인 (카드수수료 유무, 대관 취소 수수료 등) | | | &gt; | | | &gt; ▶ 신규 수익사업으로 회계계정과목 필요시 계정과목 추가 | | | &gt; | | | &gt; ▶ 수입결의서 작성 방법 (<strong>※ 회계매뉴얼 참고)</strong> | | | | | | - 입금 방식에 따라 ERP상의 수입결의 방법 상이하므로 재무회계팀 담당자와 협의 | | | | | | - 공연장 대관, 공간 대관 | | | | | | &gt; [회계매뉴얼 p55 수입결의등록(전자세금계산서/전자계산서/현금영수증)] 또는 [회계매뉴얼 p58 수입결의등록(신용카드/카드전자지급수단)] | | | | | | - 인세수입 : [회계매뉴얼 p55 수입결의등록(전자세금계산서/전자계산서/현금영수증)] | | | | | | - 기자재대여 : [회계매뉴얼 p55 수입결의등록(전자세금계산서/전자계산서/현금영수증)] | | | | | | - 공연수입 : [회계매뉴얼 p62 수입금이 통합되어 입금되는 결제사 매출 건 등] | +-----------------+-----------------------------------------------------------------------------------------------------------------------------------------+ | &gt; 지출처리 방법 | &gt; ▶ 공과금 등 안분 : 공통비용의 경우(공과금 등) 면적별로(또는 기타 합리적 구분방법) 비용처리 (※ 재무회계팀 담당자 사전협의) | | | &gt; | | | &gt; ▶ (예시) 대학로센터 공과금(중 전기요금) 안분납부 현황 (상하수도, 도시가스 등 공과금 안분해야 함) | | | &gt; | | | &gt; <img src="'+r+'" alt="" width="5.021437007874016in" height="2.415415573053368in"> | | | &gt; | | | &gt; ▶ 회계단위, 세무구분 등 확인하여 지불방법별 지출결의등록 (※ 회계매뉴얼 참고) | +-----------------+-----------------------------------------------------------------------------------------------------------------------------------------+</p><blockquote><p>[※ 참고 : 회계단위]</p></blockquote><p>+------------------------------------------+----------------+------------------------+----------------------------------------+ | &gt; <strong>수익 구분</strong> | &gt; <strong>법인세법</strong> | &gt; <strong>공익법인회계기준</strong> | &gt; <strong>회계단위</strong> | +:========================================:+:==============:+:======================:+:======================================:+ | &gt; 기타수입금, 기부금 | &gt; 고유목적사업 | &gt; 공익목적사업부문 | &gt; 자체사업(S1000), 기부금사업(S2000) | +------------------------------------------+----------------+------------------------+----------------------------------------+ | &gt; 수탁사업, 기타재원사업 | &gt; 고유목적사업 | &gt; 공익목적사업부문 | &gt; 수탁사업(S4000), 기타재원사업(S5000) | +------------------------------------------+----------------+------------------------+----------------------------------------+ | &gt; 대관료, 티켓판매, 인세, 참가료 등 수입 | &gt; 수익사업 | &gt; 공익목적사업부문 | &gt; 수익사업(자체사업)(S3000) | +------------------------------------------+----------------+------------------------+----------------------------------------+ | &gt; 편의시설 (카페) 운영 | &gt; 수익사업 | &gt; 기타사업부문 | &gt; 수익사업(자체기타사업)(SO3000) | +------------------------------------------+----------------+------------------------+----------------------------------------+</p><h3 id="수익사업-개시-및-업무처리-사업부서-재무회계팀" tabindex="-1">수익사업 개시 및 업무처리 [사업부서 / 재무회계팀] <a class="header-anchor" href="#수익사업-개시-및-업무처리-사업부서-재무회계팀" aria-label="Permalink to &quot;수익사업 개시 및 업무처리 \\[사업부서 / 재무회계팀\\]&quot;">​</a></h3><ul><li>ERP(더존IU) 세금계산서 입력 방법</li></ul><blockquote><p>① 매입 (세금계산서 수령-지출결의서)</p></blockquote><ul><li><p>부가세 신고를 위해 반드시 필요한 자료이기 때문에 재무회계팀 담당자와 협의 필수</p></li><li><p>해당 사업장의 수입형태에 따라 더존IU의 [증빙정보]-[세무구분]-[불공제사유]가 정해짐</p><ul><li><p>[세무구분] : 과세(세금계산서) 또는 불공(세금계산서)</p></li><li><p>[불공제사유] : 면세사업과 관련된 분 또는 공통매입세액안분계산서분</p></li></ul></li></ul><blockquote><p>② 매출 (세금계산서(계산서) 발행-수입결의서)</p></blockquote><ul><li><p>부가세 신고를 위해 반드시 필요한 자료이기 때문에 재무회계팀 담당자와 협의 필수</p></li><li><p>해당 사업장의 수입형태에 따라 더존IU의 [세무구분]이 정해짐</p><ul><li>[세무구분] : 과세 또는 면세 등</li></ul></li></ul><blockquote><p>&lt;※ 참고 : 부가가치세 공통매입세액 안분계산&gt;</p><p>▶ 사업장 매출이 과세, 면세 둘 다 있을 경우에는 면세사업 관련해서 구입한 매입세액은 공제가 불가능함</p><p>▶ 면세매출 관련된 매입세액 중 면세비율만큼 불공제됨</p><p>▶ 매입세액에 대한 부가가치세 환급세액은 과세·면세가 혼합되어 있는 경우, 추후 안분계산을 통해 결정</p></blockquote>',84)]))}const f=n(a,[["render",i]]);export{m as __pageData,f as default};
